import React from 'react';
import DOMPurify from 'dompurify';

function CommentThread({ comments, onReply }) {
  return (
    <div className="comment-thread">
      {comments.map(comment => (
        <CommentCard key={comment.id} comment={comment} onReply={onReply} />
      ))}
    </div>
  );
}

